CREATE SCHEMA IF NOT EXISTS "public";
SET search_path TO "public";

CREATE TABLE "USERS" (
                         "id"            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                         "email"         VARCHAR(255) NOT NULL UNIQUE,
                         "password_hash" VARCHAR(255) NOT NULL,
                         "full_name"     VARCHAR(255) NOT NULL,
                         "phone"         VARCHAR(255) NOT NULL UNIQUE,
                         "role"          TEXT NOT NULL,
                         "created_at"    TIMESTAMPTZ NOT NULL,
                         "updated_at"    TIMESTAMPTZ
);

CREATE TABLE "PASSENGERS" (
                              "id"            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                              "user_id"       BIGINT NOT NULL,
                              "full_name"     VARCHAR(255) NOT NULL,
                              "date_of_birth" DATE NOT NULL,
                              "nationality"   VARCHAR(255),
                              "created_at"    TIMESTAMPTZ NOT NULL,
                              "updated_at"    TIMESTAMPTZ
);

CREATE TABLE "PASSENGER_DOCUMENTS" (
                                       "id"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                       "passenger_id"    BIGINT NOT NULL,
                                       "identity_type"   TEXT NOT NULL,
                                       "identity_number" VARCHAR(255) NOT NULL UNIQUE,
                                       "identity_expiry" DATE,
                                       "created_at"      TIMESTAMPTZ NOT NULL,
                                       "updated_at"      TIMESTAMPTZ
);

CREATE TABLE "AIRLINES" (
                            "id"                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                            "code"              VARCHAR(255) NOT NULL UNIQUE,
                            "name"              VARCHAR(255) NOT NULL,
                            "logo_url"          VARCHAR(255),
                            "free_baggage"      BOOLEAN NOT NULL,
                            "extra_baggage_fee" NUMERIC NOT NULL,
                            "created_at"        TIMESTAMPTZ NOT NULL,
                            "updated_at"        TIMESTAMPTZ
);

CREATE TABLE "AIRPORTS" (
                            "id"         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                            "iata_code"  VARCHAR(255) NOT NULL UNIQUE,
                            "name"       VARCHAR(255) NOT NULL,
                            "city"       VARCHAR(255) NOT NULL,
                            "country"    VARCHAR(255) NOT NULL,
                            "latitude"   NUMERIC,
                            "longitude"  NUMERIC,
                            "created_at" TIMESTAMPTZ NOT NULL,
                            "updated_at" TIMESTAMPTZ
);

CREATE TABLE "AIRCRAFTS" (
                             "id"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                             "airline_code_id" BIGINT NOT NULL,
                             "model"           VARCHAR(255) NOT NULL,
                             "total_seats"     INTEGER NOT NULL,
                             "business_seats"  INTEGER NOT NULL,
                             "economy_seats"   INTEGER NOT NULL,
                             "registration_no" VARCHAR(255) NOT NULL UNIQUE,
                             "created_at"      TIMESTAMPTZ NOT NULL,
                             "updated_at"      TIMESTAMPTZ
);

CREATE TABLE "FLIGHTS" (
                           "id"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                           "flight_no"       VARCHAR(255) NOT NULL,
                           "airline_code_id" BIGINT NOT NULL,
                           "aircraft_id"     BIGINT NOT NULL,
                           "origin_iata_id"  BIGINT NOT NULL,
                           "dest_iata_id"    BIGINT NOT NULL,
                           "departure_time"  TIMESTAMPTZ NOT NULL,
                           "arrival_time"    TIMESTAMPTZ NOT NULL,
                           "status"          TEXT NOT NULL,
                           "base_price"      NUMERIC NOT NULL,
                           "source"          TEXT NOT NULL,
                           "created_at"      TIMESTAMPTZ NOT NULL,
                           "updated_at"      TIMESTAMPTZ
);

CREATE TABLE "FLIGHT_SEATS" (
                                "id"           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                "flight_id"    BIGINT NOT NULL,
                                "seat_no"      VARCHAR(255) NOT NULL,
                                "cabin_class"  TEXT NOT NULL,
                                "status"       TEXT NOT NULL,
                                "price"        NUMERIC NOT NULL,
                                "held_until"   TIMESTAMPTZ,
                                "held_by_user" BIGINT,
                                "created_at"   TIMESTAMPTZ NOT NULL,
                                "updated_at"   TIMESTAMPTZ
);

CREATE TABLE "BOOKING" (
                           "id"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                           "pnr"             VARCHAR(255) NOT NULL UNIQUE,
                           "user_id"         BIGINT NOT NULL,
                           "trip_type"       TEXT NOT NULL,
                           "base_amount"     NUMERIC NOT NULL,
                           "tax_amount"      NUMERIC NOT NULL,
                           "discount_amount" NUMERIC NOT NULL,
                           "total_amount"    NUMERIC NOT NULL,
                           "status"          TEXT NOT NULL,
                           "cancel_reason"   TEXT,
                           "cancelled_by"    BIGINT,
                           "cancelled_at"    TIMESTAMPTZ,
                           "voucher_id"      BIGINT,
                           "created_at"      TIMESTAMPTZ NOT NULL,
                           "updated_at"      TIMESTAMPTZ
);

CREATE TABLE "BOOKING_LEGS" (
                                "id"         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                "booking_id" BIGINT NOT NULL,
                                "flight_id"  BIGINT NOT NULL,
                                "leg_order"  INTEGER NOT NULL,
                                "direction"  TEXT NOT NULL,
                                "created_at" TIMESTAMPTZ NOT NULL,
                                "updated_at" TIMESTAMPTZ
);

CREATE TABLE "TICKETS" (
                           "id"             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                           "booking_id"     BIGINT NOT NULL,
                           "booking_leg_id" BIGINT NOT NULL,
                           "passenger_id"   BIGINT NOT NULL,
                           "flight_seat_id" BIGINT,
                           "ticket_no"      VARCHAR(255),
                           "passenger_type" TEXT NOT NULL,
                           "price"          NUMERIC NOT NULL,
                           "status"         TEXT NOT NULL,
                           "issued_at"      TIMESTAMPTZ,
                           "created_at"     TIMESTAMPTZ NOT NULL,
                           "updated_at"     TIMESTAMPTZ
);

CREATE TABLE "ADD_ON_SERVICES" (
                                   "id"           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                   "ticket_id"    BIGINT NOT NULL,
                                   "service_type" TEXT NOT NULL,
                                   "description"  VARCHAR(255) NOT NULL,
                                   "price"        NUMERIC NOT NULL,
                                   "quantity"     INTEGER NOT NULL,
                                   "created_at"   TIMESTAMPTZ NOT NULL,
                                   "updated_at"   TIMESTAMPTZ
);

CREATE TABLE "PAYMENTS" (
                            "id"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                            "booking_id"      BIGINT NOT NULL,
                            "provider"        TEXT NOT NULL,
                            "provider_txn_id" VARCHAR(255) UNIQUE,
                            "amount"          NUMERIC NOT NULL,
                            "currency"        VARCHAR(255) NOT NULL,
                            "status"          TEXT NOT NULL,
                            "callback_data"   TEXT,
                            "paid_at"         TIMESTAMPTZ,
                            "created_at"      TIMESTAMPTZ NOT NULL,
                            "updated_at"      TIMESTAMPTZ
);

CREATE TABLE "VOUCHERS" (
                            "id"            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                            "code"          VARCHAR(255) NOT NULL UNIQUE,
                            "discount_type" TEXT NOT NULL,
                            "value"         NUMERIC NOT NULL,
                            "usage_limit"   INTEGER NOT NULL,
                            "used_count"    INTEGER NOT NULL DEFAULT 0,
                            "conditions"    JSON,
                            "valid_from"    DATE NOT NULL,
                            "valid_until"   DATE NOT NULL,
                            "version"       INTEGER NOT NULL DEFAULT 0,
                            "created_at"    TIMESTAMPTZ NOT NULL,
                            "updated_at"    TIMESTAMPTZ
);

CREATE TABLE "NOTIFICATIONS" (
                                 "id"              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                 "booking_id"      BIGINT NOT NULL,
                                 "user_id"         BIGINT NOT NULL,
                                 "type"            TEXT NOT NULL,
                                 "recipient_email" VARCHAR(255) NOT NULL,
                                 "status"          TEXT NOT NULL,
                                 "error_message"   TEXT,
                                 "sent_at"         TIMESTAMPTZ,
                                 "created_at"      TIMESTAMPTZ NOT NULL,
                                 "updated_at"      TIMESTAMPTZ
);

CREATE TABLE "AUDIT_LOGS" (
                              "id"           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                              "admin_id"     BIGINT NOT NULL,
                              "entity_type"  VARCHAR(255) NOT NULL,
                              "entity_id"    BIGINT NOT NULL,
                              "action"       TEXT NOT NULL,
                              "before_value" JSON,
                              "after_value"  JSON,
                              "created_at"   TIMESTAMPTZ NOT NULL,
                              "updated_at"   TIMESTAMPTZ
);

ALTER TABLE "PASSENGERS" ADD CONSTRAINT "fk_passengers_user_id"
    FOREIGN KEY ("user_id") REFERENCES "USERS" ("id");

ALTER TABLE "PASSENGER_DOCUMENTS" ADD CONSTRAINT "fk_passenger_documents_passenger_id"
    FOREIGN KEY ("passenger_id") REFERENCES "PASSENGERS" ("id");

ALTER TABLE "AIRCRAFTS" ADD CONSTRAINT "fk_aircrafts_airline_code_id"
    FOREIGN KEY ("airline_code_id") REFERENCES "AIRLINES" ("id");

ALTER TABLE "FLIGHTS" ADD CONSTRAINT "fk_flights_airline_code_id"
    FOREIGN KEY ("airline_code_id") REFERENCES "AIRLINES" ("id");

ALTER TABLE "FLIGHTS" ADD CONSTRAINT "fk_flights_aircraft_id"
    FOREIGN KEY ("aircraft_id") REFERENCES "AIRCRAFTS" ("id");

ALTER TABLE "FLIGHTS" ADD CONSTRAINT "fk_flights_origin_iata_id"
    FOREIGN KEY ("origin_iata_id") REFERENCES "AIRPORTS" ("id");

ALTER TABLE "FLIGHTS" ADD CONSTRAINT "fk_flights_dest_iata_id"
    FOREIGN KEY ("dest_iata_id") REFERENCES "AIRPORTS" ("id");

ALTER TABLE "FLIGHT_SEATS" ADD CONSTRAINT "fk_flight_seats_flight_id"
    FOREIGN KEY ("flight_id") REFERENCES "FLIGHTS" ("id");

ALTER TABLE "FLIGHT_SEATS" ADD CONSTRAINT "fk_flight_seats_held_by_user"
    FOREIGN KEY ("held_by_user") REFERENCES "USERS" ("id");

ALTER TABLE "BOOKING" ADD CONSTRAINT "fk_booking_user_id"
    FOREIGN KEY ("user_id") REFERENCES "USERS" ("id");

ALTER TABLE "BOOKING" ADD CONSTRAINT "fk_booking_cancelled_by"
    FOREIGN KEY ("cancelled_by") REFERENCES "USERS" ("id");

ALTER TABLE "BOOKING" ADD CONSTRAINT "fk_booking_voucher_id"
    FOREIGN KEY ("voucher_id") REFERENCES "VOUCHERS" ("id");

ALTER TABLE "BOOKING_LEGS" ADD CONSTRAINT "fk_booking_legs_booking_id"
    FOREIGN KEY ("booking_id") REFERENCES "BOOKING" ("id");

ALTER TABLE "BOOKING_LEGS" ADD CONSTRAINT "fk_booking_legs_flight_id"
    FOREIGN KEY ("flight_id") REFERENCES "FLIGHTS" ("id");

ALTER TABLE "TICKETS" ADD CONSTRAINT "fk_tickets_booking_id"
    FOREIGN KEY ("booking_id") REFERENCES "BOOKING" ("id");

ALTER TABLE "TICKETS" ADD CONSTRAINT "fk_tickets_booking_leg_id"
    FOREIGN KEY ("booking_leg_id") REFERENCES "BOOKING_LEGS" ("id");

ALTER TABLE "TICKETS" ADD CONSTRAINT "fk_tickets_passenger_id"
    FOREIGN KEY ("passenger_id") REFERENCES "PASSENGERS" ("id");

ALTER TABLE "TICKETS" ADD CONSTRAINT "fk_tickets_flight_seat_id"
    FOREIGN KEY ("flight_seat_id") REFERENCES "FLIGHT_SEATS" ("id");

ALTER TABLE "ADD_ON_SERVICES" ADD CONSTRAINT "fk_addon_services_ticket_id"
    FOREIGN KEY ("ticket_id") REFERENCES "TICKETS" ("id");

ALTER TABLE "PAYMENTS" ADD CONSTRAINT "fk_payments_booking_id"
    FOREIGN KEY ("booking_id") REFERENCES "BOOKING" ("id");

ALTER TABLE "NOTIFICATIONS" ADD CONSTRAINT "fk_notifications_booking_id"
    FOREIGN KEY ("booking_id") REFERENCES "BOOKING" ("id");

ALTER TABLE "NOTIFICATIONS" ADD CONSTRAINT "fk_notifications_user_id"
    FOREIGN KEY ("user_id") REFERENCES "USERS" ("id");

ALTER TABLE "AUDIT_LOGS" ADD CONSTRAINT "fk_audit_logs_admin_id"
    FOREIGN KEY ("admin_id") REFERENCES "USERS" ("id");


COMMENT ON COLUMN "FLIGHTS"."source" IS 'Nguồn gốc tạo ra bản ghi';
COMMENT ON COLUMN "AIRLINES"."code" IS 'Mã định danh quốc tế của hãng hàng không';
COMMENT ON COLUMN "AIRLINES"."extra_baggage_fee" IS 'Đơn giá tính tiền cho mỗi kg hành lý ký gửi khách mua thêm';
COMMENT ON COLUMN "AIRPORTS"."iata_code" IS 'Mã 3 chữ số tiêu chuẩn quốc tế của sân bay (VD: SGN, HAN)';
COMMENT ON COLUMN "AIRPORTS"."latitude" IS 'Vĩ độ địa lý của sân bay, dùng để định vị hoặc làm dữ liệu bản đồ';
COMMENT ON COLUMN "AIRPORTS"."longitude" IS 'Kinh độ địa lý của sân bay, dùng để định vị hoặc làm dữ liệu bản đồ';
COMMENT ON COLUMN "AIRCRAFTS"."model" IS 'Dòng máy bay (VD: Airbus A321, Boeing 787)';
COMMENT ON COLUMN "AIRCRAFTS"."business_seats" IS 'Số lượng ghế thuộc khoang hạng Thương gia';
COMMENT ON COLUMN "AIRCRAFTS"."economy_seats" IS 'Số lượng ghế thuộc khoang hạng Phổ thông';
COMMENT ON COLUMN "AIRCRAFTS"."registration_no" IS 'Số hiệu đăng ký vật lý (số đuôi) của máy bay thực tế (VD: VN-A321)';
COMMENT ON COLUMN "BOOKING"."pnr" IS 'Mã đặt chỗ gồm 6-8 ký tự in hoa dùng để khách hàng tra cứu chuyến bay tại sân bay hoặc trên web';
COMMENT ON COLUMN "PAYMENTS"."provider" IS 'Cổng thanh toán tích hợp được sử dụng cho giao dịch này';
COMMENT ON COLUMN "PAYMENTS"."provider_txn_id" IS 'Transaction ID do chính cổng thanh toán  sinh ra và trả về';
COMMENT ON COLUMN "PAYMENTS"."callback_data" IS 'Chuỗi JSON thô thu được từ cổng thanh toán bắn về qua luồng Callback hoặc Webhook';
COMMENT ON COLUMN "VOUCHERS"."conditions" IS 'Chuỗi cấu hình điều kiện áp dụng dưới dạng JSON';
COMMENT ON COLUMN "VOUCHERS"."version" IS 'Trường kỹ thuật dùng cho Optimistic Locking của JPA';
COMMENT ON COLUMN "NOTIFICATIONS"."error_message" IS 'Đoạn mã lỗi chi tiết trả về từ Mail Server khi trạng thái là FAILED';
COMMENT ON COLUMN "AUDIT_LOGS"."before_value" IS 'Ảnh chụp dữ liệu trạng thái TRƯỚC khi Admin bấm nút sửa';
COMMENT ON COLUMN "AUDIT_LOGS"."after_value" IS 'Ảnh chụp dữ liệu trạng thái SAU khi Admin bấm nút sửa thành công';